# Domain Taxonomies
TAXONOMY = {
    "Ethno-Racial": ["indio", "indigena", "indigina", "indijena", "indijino", "indio", "india", "espanol", "espanola", "mestiza", "aucara", "punas"],
    "Legitimacy": ["legitimo", "legitima", "natural", "espurio", "espuria", "hijo", "hija"],
    "Geographic": ["pampamarca", "chacralla", "aucara"]
}

# Legal Abbreviations Mapping
ABBREVIATIONS = {
    "hn": "hijo natural",
    "hl": "hijo legitimo",
    "id": "indigena",
    "hl hijo": "hijo legitimo",
    "hl hija": "hija legitima"
}

def normalize_term(term):
    """Normalizes a term based on abbreviations, fuzzy matching, and taxonomy."""
    term = term.lower().strip().replace(".", "")

    # 1. Resolve Abbreviations
    if term in ABBREVIATIONS:
        return ABBREVIATIONS[term]

    # 2. Fuzzy Match against Taxonomy (handling scribal errors like 'indijena')
    for category, terms in TAXONOMY.items():
        matches = get_close_matches(term, terms, n=1, cutoff=0.7)
        if matches:
            return matches[0]

    return term

def parse_clusters(data):
    clusters = {}
    lines = [line for line in data.strip().split('\n') if line]

    for line in lines:
        cluster_id = line.split(':')[0].strip()
        terms_raw = line.split(':')[1].split(',')

        normalized_terms = set()
        for raw_term in terms_raw:
            norm = normalize_term(raw_term)

            # Classify into facets
            facets = {}
            for category, terms in TAXONOMY.items():
                if norm in terms:
                    facets[category] = norm

            # If it's a multi-word term (e.g., "hijo natural"), 
            # we check if components exist in taxonomy
            if " " in norm:
                parts = norm.split()
                for p in parts:
                    for category, terms in TAXONOMY.items():
                        if p in terms:
                            facets[category] = p

            # Update the set with the structured dictionary
            # We use a list of dicts to preserve multiple attributes per term
            normalized_terms.add(norm)

        clusters[cluster_id] = list(normalized_terms)

    # Final structure: Map each cluster to its unique canonical attributes
    final_output = {}
    for cid, terms in clusters.items():
        attributes = set()
        for t in terms:
            # Extract facets for each term
            for category, terms_list in TAXONOMY.items():
                if t in terms_list:
                    attributes.add((category, t))

        # Convert set of tuples to a dictionary of lists
        attr_dict = {}
        for cat, val in attributes:
            if cat not in attr_dict: attr_dict[cat] = set()
            attr_dict[cat].add(val)

        final_output[cid] = {k: list(v) for k, v in attr_dict.items()}

    return final_output

if __name__ == "__main__":
    result = parse_clusters(log_data)
    print(json.dumps(result, indent=4, ensure_ascii=False))
